-- 26 LOOKUP_MASTER_DETAIL SEGMENT1/LOOKUP_TYPE LIKE 'DMF0049%' 1행 [20260828]
-- ── SCM_ADM_LOOKUP_MASTER_DETAIL 1행 MERGE (ON = PK 실측 ['LOOKUP_TYPE', 'SEGMENT1', 'SEGMENT2', 'SEGMENT3', 'SEGMENT4', 'SEGMENT5']) [SEGMENT1] ──
MERGE INTO SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL T USING (SELECT 'MENU_AUTH_BY_DIVISION' AS LOOKUP_TYPE, 'DMF0049' AS SEGMENT1, '40' AS SEGMENT2, '소형' AS SEGMENT3, 'ADMIN' AS SEGMENT4, '-' AS SEGMENT5, 0 AS DISPLAY_SEQ, 'Y' AS VALID_YN, 'System Administrator인 경우에는 해당 부서가 아니어도 화면이 조회되도록 함.' AS DESCRIPTION, 'jssbae' AS CREATED_BY, TO_DATE('2025-08-04 10:38:49','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'jssbae' AS LAST_UPDATED_BY, TO_DATE('2025-08-04 10:38:49','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE, NULL AS ATTRIBUTE1, NULL AS ATTRIBUTE2, NULL AS ATTRIBUTE3, NULL AS ATTRIBUTE4, NULL AS ATTRIBUTE5, NULL AS ATTRIBUTE6, NULL AS ATTRIBUTE7, NULL AS ATTRIBUTE8, NULL AS ATTRIBUTE9, NULL AS ATTRIBUTE10, NULL AS ATTRIBUTE11, NULL AS ATTRIBUTE12, NULL AS ATTRIBUTE13, NULL AS ATTRIBUTE14, NULL AS ATTRIBUTE15 FROM DUAL) S ON (T.LOOKUP_TYPE=S.LOOKUP_TYPE AND T.SEGMENT1=S.SEGMENT1 AND T.SEGMENT2=S.SEGMENT2 AND T.SEGMENT3=S.SEGMENT3 AND T.SEGMENT4=S.SEGMENT4 AND T.SEGMENT5=S.SEGMENT5)
WHEN MATCHED THEN UPDATE SET T.DISPLAY_SEQ=S.DISPLAY_SEQ, T.VALID_YN=S.VALID_YN, T.DESCRIPTION=S.DESCRIPTION, T.LAST_UPDATED_BY=S.LAST_UPDATED_BY, T.LAST_UPDATE_DATE=S.LAST_UPDATE_DATE, T.ATTRIBUTE1=S.ATTRIBUTE1, T.ATTRIBUTE2=S.ATTRIBUTE2, T.ATTRIBUTE3=S.ATTRIBUTE3, T.ATTRIBUTE4=S.ATTRIBUTE4, T.ATTRIBUTE5=S.ATTRIBUTE5, T.ATTRIBUTE6=S.ATTRIBUTE6, T.ATTRIBUTE7=S.ATTRIBUTE7, T.ATTRIBUTE8=S.ATTRIBUTE8, T.ATTRIBUTE9=S.ATTRIBUTE9, T.ATTRIBUTE10=S.ATTRIBUTE10, T.ATTRIBUTE11=S.ATTRIBUTE11, T.ATTRIBUTE12=S.ATTRIBUTE12, T.ATTRIBUTE13=S.ATTRIBUTE13, T.ATTRIBUTE14=S.ATTRIBUTE14, T.ATTRIBUTE15=S.ATTRIBUTE15
WHEN NOT MATCHED THEN INSERT (LOOKUP_TYPE, SEGMENT1, SEGMENT2, SEGMENT3, SEGMENT4, SEGMENT5, DISPLAY_SEQ, VALID_YN, DESCRIPTION, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15) VALUES (S.LOOKUP_TYPE, S.SEGMENT1, S.SEGMENT2, S.SEGMENT3, S.SEGMENT4, S.SEGMENT5, S.DISPLAY_SEQ, S.VALID_YN, S.DESCRIPTION, S.CREATED_BY, S.CREATION_DATE, S.LAST_UPDATED_BY, S.LAST_UPDATE_DATE, S.ATTRIBUTE1, S.ATTRIBUTE2, S.ATTRIBUTE3, S.ATTRIBUTE4, S.ATTRIBUTE5, S.ATTRIBUTE6, S.ATTRIBUTE7, S.ATTRIBUTE8, S.ATTRIBUTE9, S.ATTRIBUTE10, S.ATTRIBUTE11, S.ATTRIBUTE12, S.ATTRIBUTE13, S.ATTRIBUTE14, S.ATTRIBUTE15);
COMMIT;
